package br.oab.minha;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import android.graphics.Color;import android.text.InputType;import java.net.*;import java.io.*;import org.json.JSONObject;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity{
 EditText endpoint,token,question;TextView result;Button send;
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);l.setBackgroundColor(Color.rgb(20,36,59));sc.setFillViewport(true);sc.addView(l);setContentView(sc);
 TextView title=new TextView(this);title.setText("Minha Aprovação OAB — Beta 9.3 — Diagnóstico\nProfessor jurídico Gemini");title.setTextSize(24);title.setTextColor(0xffefcd83);l.addView(title);
 endpoint=new EditText(this);endpoint.setHint("URL HTTPS do servidor /api/tutor");endpoint.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);endpoint.setText(getPreferences(0).getString("endpoint","https://app-juridico.sgtfpatrola.workers.dev/api/tutor"));l.addView(endpoint);
 token=new EditText(this);token.setHint("Token privado do servidor");token.setInputType(129);l.addView(token);
 question=new EditText(this);question.setHint("Sua dúvida jurídica");question.setMinLines(3);l.addView(question);
 send=new Button(this);send.setText("Perguntar ao professor");l.addView(send);result=new TextView(this);result.setTextColor(Color.WHITE);result.setTextIsSelectable(true);l.addView(result);
 Button diagnostic=new Button(this);diagnostic.setText("Testar DNS e servidor");l.addView(diagnostic);
 diagnostic.setOnClickListener(v->{String u=endpoint.getText().toString().trim();diagnostic.setEnabled(false);result.setText("Iniciando diagnóstico…");new Thread(()->{StringBuilder report=new StringBuilder();HttpURLConnection c=null;String stage="URL";long start=android.os.SystemClock.elapsedRealtime();try{URL target=new URL(u);if(!"https".equals(target.getProtocol()))throw new IOException("Use HTTPS");stage="DNS";long a=android.os.SystemClock.elapsedRealtime();InetAddress[] addresses=InetAddress.getAllByName(target.getHost());report.append("DNS: OK (").append(addresses.length).append(" endereços, ").append(android.os.SystemClock.elapsedRealtime()-a).append(" ms)\n");stage="HTTPS GET";a=android.os.SystemClock.elapsedRealtime();c=(HttpURLConnection)new URL(target.getProtocol(),target.getHost(),target.getPort(),"/").openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/json");int status=c.getResponseCode();report.append("Servidor: HTTP ").append(status).append(" (").append(android.os.SystemClock.elapsedRealtime()-a).append(" ms)\n");stage="Resposta GET";if(status==200){try(InputStream in=c.getInputStream()){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buf=new byte[1024];int n;while((n=in.read(buf))!=-1&&bytes.size()<8192)bytes.write(buf,0,n);JSONObject data=new JSONObject(bytes.toString("UTF-8"));report.append("Status: ").append(data.optString("status","ausente")).append("\nVersão: ").append(data.optString("version","ausente"));}}}catch(Exception e){report.append(stage).append(": ").append(e.getClass().getSimpleName()).append(" — ").append(e.getMessage());}finally{if(c!=null)c.disconnect();}report.append("\nTempo total: ").append(android.os.SystemClock.elapsedRealtime()-start).append(" ms");String m=report.toString();runOnUiThread(()->{result.setText(m);diagnostic.setEnabled(true);});}).start();});
 TextView note=new TextView(this);note.setText("Protótipo de conexão — confira a legislação oficial.\nDesenvolvido por ChatGPT e Filipe Patrocínio.");l.addView(note);
 send.setOnClickListener(v->{String u=endpoint.getText().toString().trim(),t=token.getText().toString(),q=question.getText().toString().trim();if(!u.startsWith("https://")||t.isEmpty()||q.isEmpty()){result.setText("Informe endereço HTTPS, token e pergunta.");return;}getPreferences(0).edit().putString("endpoint",u).apply();send.setEnabled(false);result.setText("Consultando Gemini…");new Thread(()->{String msg;try{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(30000);c.setReadTimeout(120000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Accept","application/json");c.setRequestProperty("Authorization","Bearer "+t);try(OutputStream o=c.getOutputStream()){o.write(new JSONObject().put("question",q).toString().getBytes(StandardCharsets.UTF_8));}int status=c.getResponseCode();InputStream in=status<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream buf=new ByteArrayOutputStream();if(in!=null){try(InputStream i=in){byte[] a=new byte[4096];int n;while((n=i.read(a))!=-1)buf.write(a,0,n);}}String raw=buf.toString("UTF-8");try{JSONObject d=new JSONObject(raw);msg=status==200?d.optString("answer","Resposta vazia"):"HTTP "+status+": "+d.optString("error","Erro do servidor");}catch(org.json.JSONException e){msg="HTTP "+status+" | Tipo: "+c.getContentType()+" | Servidor retornou "+(raw.trim().startsWith("<")?"HTML em vez de JSON":"dados não JSON")+" | Cloudflare Ray: "+c.getHeaderField("cf-ray");}c.disconnect();}catch(java.net.SocketTimeoutException e){msg="Tempo limite excedido. O servidor ou Gemini demorou a responder. Tente novamente.";}catch(Exception e){msg="Falha de comunicação: "+e.getMessage();}String m=msg;runOnUiThread(()->{result.setText(m);send.setEnabled(true);});}).start();});}
}